type Job struct {
	ID    int
	Payload string
}

// WorkerPool manages a bounded pool of goroutines that process jobs
// from a channel with graceful shutdown support.
type WorkerPool struct {
	numWorkers int
	jobChan    chan Job
	wg         sync.WaitGroup
	mu         sync.Mutex
